'use strict';
const assert=require('node:assert/strict'),http=require('node:http');
async function ownedModelList(){
 let actor=true,judge=true,generation=0,tags=0,rejectedNonTagRequests=0;
 const server=http.createServer((req,res)=>{if(req.method!=='GET'||req.url!=='/api/tags'){rejectedNonTagRequests++;if(['/api/chat','/api/generate'].includes(req.url))generation++;res.writeHead(503);return res.end('No inference permitted');}tags++;if(tags>64){res.writeHead(429);return res.end('Model-list request limit');}res.setHeader('content-type','application/json');res.end(JSON.stringify({models:[...(actor?[{name:'owned-actor'}]:[]),...(judge?[{name:'owned-judge'}]:[])]}));});
 await new Promise((resolve,reject)=>{server.once('error',reject);server.listen(0,'127.0.0.1',resolve);});
 return {port:server.address().port,origin:'http://127.0.0.1:'+server.address().port,set(value){actor=value.actor;judge=value.judge;},counts:()=>({tags,generation,rejectedNonTagRequests}),async close(){server.closeAllConnections();await new Promise(resolve=>server.close(resolve));}};
}
async function qualifyHeaderSeed({identity,migration}){
 const seed=require('../../server/database/postgres/workshopPlatformSeed'),curriculum=require('../../server/config/secureshopCurriculum'),hints=require('../../server/data/workshopHints'),id='ss_mail_header_construction',key='secureshop_agent_security';
 const read=async()=>(await identity.query('SELECT objective_id,is_enabled,catalog_active,hint_content,solution_content FROM workshop_platform.objectives WHERE workshop_key=$1 ORDER BY objective_id',[key])).rows;
 const fresh=await read(),header=fresh.find(row=>row.objective_id===id);assert.equal(header.is_enabled,false);assert.equal(header.catalog_active,true);assert.deepEqual(header.hint_content,curriculum.HINTS[id]);assert.deepEqual(header.solution_content,curriculum.SOLUTIONS[id]);
 const pendingHint={...curriculum.HINTS[id],hints:['This objective is registered for curriculum planning but is not yet available for instructor enablement.','Its owner-bound evidence, reset, and connected application path must be qualified before release.']},pendingSolution={...curriculum.SOLUTIONS[id],hints:pendingHint.hints,examples:[{action:'Unavailable',explanation:'This pending objective cannot be enabled until its connected evidence path is qualified.'}],approach:'Unavailable until the server-owned evidence, reset, and application path are qualified.',tips:['Instructor enablement is intentionally blocked.']};
 const solutions=seed.solutionFixtures();await seed.seedWorkshopPlatform(migration,{hints:{...hints,[key]:{...hints[key],[id]:pendingHint}},solutions:{...solutions,[key]:{...solutions[key],[id]:pendingSolution}}});assert.deepEqual((await read()).find(r=>r.objective_id===id).hint_content,pendingHint);assert.deepEqual((await read()).find(r=>r.objective_id===id).solution_content,pendingSolution);
 await seed.seedWorkshopPlatform(migration);assert.deepEqual(await read(),fresh);await seed.seedWorkshopPlatform(migration);assert.deepEqual(await read(),fresh);
 const config=require('../../server/database/postgres/workshopConfigRepository').createWorkshopConfigRepository(identity,{isSecureShopReady:()=>true});const custom={...header.hint_content,hints:['Instructor-owned header guidance']},customSolution={...header.solution_content,examples:[{action:'Instructor-owned action',explanation:'Instructor-owned explanation'}]};await config.updateHintContent(key,id,custom);await config.updateSolutionContent(key,id,customSolution);await seed.seedWorkshopPlatform(migration);await seed.seedWorkshopPlatform(migration);assert.deepEqual((await read()).find(r=>r.objective_id===id).hint_content,custom);assert.deepEqual((await read()).find(r=>r.objective_id===id).solution_content,customSolution);
 // Restore through supported instructor mutation, not provenance-forging SQL.
 await config.updateHintContent(key,id,header.hint_content);await config.updateSolutionContent(key,id,header.solution_content);assert.deepEqual((await read()).filter(r=>r.objective_id!==id),fresh.filter(r=>r.objective_id!==id));
 return {priorStateScope:'Representative managed pending canonical content, staged through canonical seed overrides; not an imported historical installation',freshDefaultDisabled:true,managedPendingUpgrade:true,secondRunNoop:true,instructorPreserved:true,otherRowsUnchanged:JSON.stringify((await read()).filter(r=>r.objective_id!==id))===JSON.stringify(fresh.filter(r=>r.objective_id!==id))};
}
module.exports={ownedModelList,qualifyHeaderSeed};
